from collections import deque


def kin_distance(parents: dict, a: str, b: str):
    def ancestor_distances(start):
        dist = {start: 0}
        q = deque([start])

        while q:
            person = q.popleft()
            d = dist[person]
            for parent in parents.get(person, ()):
                if parent not in dist:
                    dist[parent] = d + 1
                    q.append(parent)

        return dist

    da = ancestor_distances(a)
    db = ancestor_distances(b)

    best = None
    for person, da_dist in da.items():
        db_dist = db.get(person)
        if db_dist is not None:
            if best is None or (da_dist + db_dist, da_dist) < (best[0] + best[1], best[0]):
                best = (da_dist, db_dist)

    return best
