from __future__ import annotations

import re

_SLOT_RE = re.compile(r"[A-Z][1-9][0-9]?")


def _parse_slot(slot: str) -> tuple[str, int]:
    if not _SLOT_RE.fullmatch(slot):
        raise ValueError(f"invalid slot: {slot!r}")
    return slot[0], int(slot[1:])


def expand_slots(spec: str) -> list[str]:
    if not spec.strip():
        return []

    result: list[str] = []
    present: set[str] = set()

    for raw_token in spec.split(","):
        token = raw_token.strip()
        if not token:
            raise ValueError("empty token in slot spec")

        removal = False
        if token.startswith("!"):
            removal = True
            token = token[1:]

        if "-" in token:
            parts = token.split("-")
            if len(parts) != 2:
                raise ValueError(f"invalid range token: {token!r}")

            letter1, start = _parse_slot(parts[0])
            letter2, end = _parse_slot(parts[1])

            if letter1 != letter2:
                raise ValueError(f"range letters must match: {token!r}")

            if start <= end:
                numbers = range(start, end + 1)
            else:
                numbers = range(start, end - 1, -1)

            slots = [f"{letter1}{n}" for n in numbers]
        else:
            letter, number = _parse_slot(token)
            slots = [f"{letter}{number}"]

        if removal:
            for slot in slots:
                if slot in present:
                    result.remove(slot)
                    present.remove(slot)
        else:
            for slot in slots:
                if slot not in present:
                    result.append(slot)
                    present.add(slot)

    return result
