def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    order_customer = {}
    order_amount = {}
    order_cancelled = {}
    customer_total = {}
    first_buy_ts = {}

    for _, event in sorted(
        enumerate(events),
        key=lambda item: (item[1]["ts"], item[0]),
    ):
        etype = event["type"]
        order = event["order"]
        ts = event["ts"]

        if etype == "buy":
            if order in order_customer:
                continue

            customer = event["customer"]
            cents = event["cents"]

            order_customer[order] = customer
            order_amount[order] = cents
            order_cancelled[order] = False

            customer_total[customer] = customer_total.get(customer, 0) + cents
            if customer not in first_buy_ts:
                first_buy_ts[customer] = ts

        elif etype == "refund":
            if order in order_customer and not order_cancelled[order]:
                cents = event["cents"]
                old = order_amount[order]
                new = old - cents
                if new < 0:
                    new = 0

                if new != old:
                    order_amount[order] = new
                    customer = order_customer[order]
                    customer_total[customer] += new - old

        elif etype == "cancel":
            if order in order_customer and not order_cancelled[order]:
                old = order_amount[order]
                if old:
                    customer = order_customer[order]
                    customer_total[customer] -= old
                order_amount[order] = 0
                order_cancelled[order] = True

    ranked = [(customer, total) for customer, total in customer_total.items() if total > 0]
    ranked.sort(key=lambda x: (-x[1], first_buy_ts[x[0]], x[0]))
    return ranked[:k]
